from django.db import migrations, models
from django.utils.text import slugify


def make_existing_companies_active(apps, schema_editor):
    Company = apps.get_model('companies', 'Company')
    for company in Company.objects.all():
        company.status = 'active'
        if not company.slug:
            base_slug = slugify(company.name) or f"company-{company.pk}"
            slug = base_slug
            counter = 1
            while Company.objects.filter(slug=slug).exclude(pk=company.pk).exists():
                slug = f"{base_slug}-{counter}"
                counter += 1
            company.slug = slug
        company.save(update_fields=['status', 'slug'])


